-- Each vehicle has exactly one sensordata row. Let me check total counts
SELECT COUNT(*) FROM sensordata;
SELECT COUNT(DISTINCT vehsenseref) FROM sensordata;

-- Check date columns available - shipments has timemark, transportinfo has departsite/currentsite but those are text
-- Let's check what dates are in shipments and sensordata
SELECT MIN(timemark), MAX(timemark) FROM shipments;
SELECT MIN(alerttime), MAX(alerttime) FROM sensordata;

-- Let me check if maybe the issue is that I need to use shipments table for something
-- Check what columns in shipments could relate to handling
SELECT DISTINCT qualcheck FROM shipments;
SELECT DISTINCT integritymark FROM shipments;

-- Check all columns across all tables for handle-related columns
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%handle%' OR column_name LIKE '%quality%' OR column_name LIKE '%reliab%';

-- Check for any boolean or flag columns that might indicate reliability
SELECT column_name, data_type FROM information_schema.columns 
WHERE table_name = 'transportinfo' AND (data_type LIKE '%bool%' OR column_name LIKE '%flag%');

-- Maybe "handling quality" comes from a different source entirely
-- Check regulatoryandmaintenance for any quality-related columns
SELECT * FROM regulatoryandmaintenance LIMIT 1;

-- Maybe handling quality is based on qualcheck from shipments
-- Let me check if there's a pattern where Passed qualcheck = reliable
SELECT s.qualcheck, COUNT(*) FROM shipments s GROUP BY s.qualcheck;

-- Check all columns across all user tables for any handle-related data
SELECT table_name, column_name FROM information_schema.columns 
WHERE table_schema = 'public' AND (column_name ILIKE '%handle%' OR column_name ILIKE '%event%');
